fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    
    // Handle edge cases: empty or single-element arrays
    if n <= 1 {
        return numbers;
    }
    
    // Result will have length 2 * n - 1
    let mut result = Vec::with_capacity(2 * n - 1);
    
    // Add first n-1 elements, each followed by a delimiter
    for i in 0..n - 1 {
        result.push(numbers[i]);
        result.push(delimiter);
    }
    
    // Add the last element (without a delimiter after it)
    result.push(numbers[n - 1]);
    
    result
}